export const calculateWPM = (wordCount, durationMs) => {
  const minutes = durationMs / (1000 * 60);
  return Math.round(wordCount / minutes);
};

export const calculateAccuracy = (correctWords, totalWords) => {
  return Math.round((correctWords / totalWords) * 100) / 100;
};

export const classifyError = (token) => {
  if (token.confidence < 0.5) return 'mispronunciation';
  if (token.status === 'omitted') return 'omission';
  if (token.status === 'inserted') return 'insertion';
  if (token.status === 'repeated') return 'repetition';
  if (token.pauseAfter > 2000) return 'longPause';
  return 'correct';
};

export const getReadingLevel = (wpm, accuracy) => {
  if (wpm >= 120 && accuracy >= 0.95) return 'Excelente';
  if (wpm >= 100 && accuracy >= 0.90) return 'Muy Bueno';
  if (wpm >= 80 && accuracy >= 0.85) return 'Bueno';
  if (wpm >= 60 && accuracy >= 0.75) return 'En Desarrollo';
  return 'Necesita Apoyo';
};

export const generatePracticeWords = (difficultWords) => {
  return difficultWords.map(word => ({
    word: word.word,
    syllables: splitIntoSyllables(word.word),
    practiceType: word.confidence < 0.4 ? 'syllable' : 'whole',
    difficulty: word.confidence < 0.3 ? 'high' : 'medium'
  }));
};

export const splitIntoSyllables = (word) => {
  // Simplified Spanish syllable splitting
  const vowels = 'aeiouáéíóúü';
  const syllables = [];
  let currentSyllable = '';
  
  for (let i = 0; i < word.length; i++) {
    currentSyllable += word[i];
    
    if (vowels.includes(word[i].toLowerCase())) {
      if (i < word.length - 1 && !vowels.includes(word[i + 1].toLowerCase())) {
        if (i < word.length - 2 && !vowels.includes(word[i + 2].toLowerCase())) {
          currentSyllable += word[i + 1];
          i++;
        }
        syllables.push(currentSyllable);
        currentSyllable = '';
      }
    }
  }
  
  if (currentSyllable) syllables.push(currentSyllable);
  return syllables.length > 0 ? syllables : [word];
};

export const formatTime = (seconds) => {
  const mins = Math.floor(seconds / 60);
  const secs = seconds % 60;
  return `${mins}:${secs.toString().padStart(2, '0')}`;
};