import React from 'react';
import { motion } from 'framer-motion';
import { BookOpen, Users, Home, Sparkles } from 'lucide-react';
import { useNavigate, useLocation } from 'react-router-dom';

const Navigation = () => {
  const navigate = useNavigate();
  const location = useLocation();

  const navItems = [
    { path: '/', icon: Home, label: '¡A Leer!' },
    { path: '/teacher', icon: Users, label: 'Mi Tablero' }
  ];

  return (
    <motion.nav
      className="fixed top-6 left-1/2 transform -translate-x-1/2 z-50"
      initial={{ opacity: 0, y: -50 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.8, type: "spring", stiffness: 120 }}
    >
      <div className="bg-white/90 backdrop-blur-xl border border-gray-200/50 rounded-3xl p-3 shadow-xl">
        <div className="flex items-center gap-3">
          <motion.div 
            className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-blue-500 to-purple-600 rounded-2xl text-white font-bold text-lg shadow-md"
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ type: "spring", stiffness: 260, damping: 20, delay: 0.2 }}
          >
            <Sparkles className="w-6 h-6 fill-current" />
            FluidezLectora
          </motion.div>
          
          <div className="h-8 w-px bg-gray-300"></div>
          
          <div className="flex gap-2">
            {navItems.map(({ path, icon: Icon, label }) => (
              <motion.button
                key={path}
                onClick={() => navigate(path)}
                className={`flex items-center gap-2 px-5 py-3 rounded-xl font-bold text-lg transition-all transform hover:scale-105 ${
                  location.pathname === path
                    ? 'bg-blue-100 text-blue-700 shadow-sm'
                    : 'text-gray-600 hover:text-gray-900 hover:bg-gray-100'
                }`}
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
              >
                <Icon className="w-5 h-5" />
                {label}
              </motion.button>
            ))}
          </div>
        </div>
      </div>
    </motion.nav>
  );
};

export default Navigation;