import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Users, 
  TrendingUp, 
  Download, 
  Filter, 
  Search,
  Calendar,
  BarChart3,
  BookOpen,
  Award,
  AlertTriangle,
  Smile,
  Frown,
  Star,
  Eye,
  X 
} from 'lucide-react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, BarChart, Bar } from 'recharts';
import { mockStudents, mockTrendData, studentReadingHistory } from '../data/mockResults'; // Importa studentReadingHistory

const TeacherDashboard = () => {
  const [selectedClass, setSelectedClass] = useState('4º A');
  const [searchTerm, setSearchTerm] = useState('');
  const [sortBy, setSortBy] = useState('name');
  const [filteredStudents, setFilteredStudents] = useState([]);
  const [selectedStudent, setSelectedStudent] = useState(null);

  useEffect(() => {
    // Asegúrate de que mockStudents esté definido antes de intentar filtrar
    const studentsToFilter = mockStudents || []; 

    const studentsInClass = studentsToFilter.filter(student => student.grade === selectedClass);
    
    const searchedStudents = studentsInClass.filter(student => 
      student.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const sortedStudents = [...searchedStudents].sort((a, b) => {
      switch (sortBy) {
        case 'wpm':
          return b.stats.wpm - a.stats.wpm;
        case 'accuracy':
          return b.stats.accuracy - a.stats.accuracy;
        case 'lastReading':
          return new Date(b.lastReading) - new Date(a.lastReading);
        default:
          return a.name.localeCompare(b.name);
      }
    });
    setFilteredStudents(sortedStudents);
  }, [selectedClass, searchTerm, sortBy]);

  const classStats = {
    totalStudents: filteredStudents.length,
    averageWPM: filteredStudents.length > 0 ? Math.round(filteredStudents.reduce((sum, s) => sum + s.stats.wpm, 0) / filteredStudents.length) : 0,
    averageAccuracy: filteredStudents.length > 0 ? Math.round(filteredStudents.reduce((sum, s) => sum + s.stats.accuracy, 0) / filteredStudents.length * 100) : 0,
    needsSupport: filteredStudents.filter(s => s.stats.wpm < 80 || s.stats.accuracy < 0.8).length
  };

  const exportData = () => {
    const csvContent = [
      ['Nombre', 'Curso', 'WPM', 'Precisión', 'Errores', 'Última Lectura', 'Total Lecturas'],
      ...filteredStudents.map(student => [
        student.name,
        student.grade,
        student.stats.wpm,
        `${Math.round(student.stats.accuracy * 100)}%`,
        `${Math.round(student.stats.errorRate * 100)}%`,
        student.lastReading,
        student.stats.totalReadings
      ])
    ].map(row => row.join(',')).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `reporte-lectura-${selectedClass}-${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
  };

  const getPerformanceColor = (wpm, accuracy) => {
    if (wpm >= 120 && accuracy >= 0.95) return 'text-green-800 bg-green-200';
    if (wpm >= 100 && accuracy >= 0.90) return 'text-blue-800 bg-blue-200';
    if (wpm >= 80 && accuracy >= 0.85) return 'text-yellow-800 bg-yellow-200';
    return 'text-red-800 bg-red-200';
  };

  const getPerformanceLabel = (wpm, accuracy) => {
    if (wpm >= 120 && accuracy >= 0.95) return '¡Estrella!';
    if (wpm >= 100 && accuracy >= 0.90) return '¡Genial!';
    if (wpm >= 80 && accuracy >= 0.85) return '¡Bien!';
    return '¡A practicar!';
  };

  const openStudentDetails = (student) => {
    setSelectedStudent(student);
  };

  const closeStudentDetails = () => {
    setSelectedStudent(null);
  };

  return (
    <div className="max-w-7xl mx-auto p-6">
      {/* Header */}
      <motion.div
        className="bg-white/90 backdrop-blur-xl border border-gray-200 rounded-3xl p-8 mb-8 shadow-xl"
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
      >
        <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-6">
          <div className="flex items-center gap-4">
            <motion.div 
              className="p-3 bg-gradient-to-br from-blue-500 to-purple-600 rounded-2xl"
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              transition={{ type: "spring", stiffness: 260, damping: 20 }}
            >
              <Users className="w-8 h-8 text-white" />
            </motion.div>
            <div>
              <h1 className="text-3xl font-bold bg-gradient-to-r from-blue-600 to-purple-700 bg-clip-text text-transparent">
                ¡Mi Tablero Mágico!
              </h1>
              <p className="text-gray-600 font-medium text-lg">
                Así van mis pequeños lectores en {selectedClass}
              </p>
            </div>
          </div>

          <div className="flex flex-col sm:flex-row gap-4">
            <select
              value={selectedClass}
              onChange={(e) => setSelectedClass(e.target.value)}
              className="px-4 py-2 bg-white border border-gray-300 rounded-xl font-medium focus:outline-none focus:ring-2 focus:ring-blue-500 text-lg"
            >
              <option value="4º A">4º A</option>
              <option value="4º B">4º B</option>
              <option value="5º A">5º A</option>
            </select>

            <motion.button
              onClick={exportData}
              className="flex items-center gap-2 px-5 py-3 bg-gradient-to-r from-green-500 to-emerald-600 text-white rounded-xl font-bold shadow-lg hover:shadow-xl transition-all transform hover:scale-105"
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
            >
              <Download className="w-5 h-5" />
              Descargar Reporte
            </motion.button>
          </div>
        </div>
      </motion.div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
        <motion.div
          className="bg-white/90 backdrop-blur-sm border border-blue-300 rounded-2xl p-6 shadow-lg"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
        >
          <div className="flex items-center gap-3 mb-3">
            <Users className="w-7 h-7 text-blue-600" />
            <h3 className="font-bold text-gray-900 text-lg">Mis Estudiantes</h3>
          </div>
          <div className="text-4xl font-bold text-blue-600">
            {classStats.totalStudents}
          </div>
        </motion.div>

        <motion.div
          className="bg-white/90 backdrop-blur-sm border border-green-300 rounded-2xl p-6 shadow-lg"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
        >
          <div className="flex items-center gap-3 mb-3">
            <TrendingUp className="w-7 h-7 text-green-600" />
            <h3 className="font-bold text-gray-900 text-lg">Velocidad Promedio</h3>
          </div>
          <div className="text-4xl font-bold text-green-600">
            {classStats.averageWPM}
          </div>
        </motion.div>

        <motion.div
          className="bg-white/90 backdrop-blur-sm border border-purple-300 rounded-2xl p-6 shadow-lg"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
        >
          <div className="flex items-center gap-3 mb-3">
            <Award className="w-7 h-7 text-purple-600" />
            <h3 className="font-bold text-gray-900 text-lg">Precisión General</h3>
          </div>
          <div className="text-4xl font-bold text-purple-600">
            {classStats.averageAccuracy}%
          </div>
        </motion.div>

        <motion.div
          className="bg-white/90 backdrop-blur-sm border border-orange-300 rounded-2xl p-6 shadow-lg"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.4 }}
        >
          <div className="flex items-center gap-3 mb-3">
            <AlertTriangle className="w-7 h-7 text-orange-600" />
            <h3 className="font-bold text-gray-900 text-lg">¡Necesitan Ayuda!</h3>
          </div>
          <div className="text-4xl font-bold text-orange-600">
            {classStats.needsSupport}
          </div>
        </motion.div>
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-8">
        <motion.div
          className="bg-white/90 backdrop-blur-xl border border-gray-200 rounded-2xl p-6 shadow-xl"
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ delay: 0.5 }}
        >
          <h3 className="text-xl font-bold text-gray-900 mb-4">
            ¡Cómo van mejorando! (WPM)
          </h3>
          <ResponsiveContainer width="100%" height={250}>
            <LineChart data={mockTrendData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e0e0e0" />
              <XAxis dataKey="date" />
              <YAxis />
              <Tooltip />
              <Line 
                type="monotone" 
                dataKey="wpm" 
                stroke="#3B82F6" 
                strokeWidth={4}
                dot={{ fill: '#3B82F6', strokeWidth: 2, r: 6 }}
                activeDot={{ r: 8 }}
              />
            </LineChart>
          </ResponsiveContainer>
        </motion.div>

        <motion.div
          className="bg-white/90 backdrop-blur-xl border border-gray-200 rounded-2xl p-6 shadow-xl"
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ delay: 0.6 }}
        >
          <h3 className="text-xl font-bold text-gray-900 mb-4">
            ¡Así leen mis campeones!
          </h3>
          <ResponsiveContainer width="100%" height={250}>
            <BarChart data={[
              { nivel: '¡Estrella!', cantidad: filteredStudents.filter(s => s.stats.wpm >= 120 && s.stats.accuracy >= 0.95).length },
              { nivel: '¡Genial!', cantidad: filteredStudents.filter(s => s.stats.wpm >= 100 && s.stats.accuracy >= 0.90 && !(s.stats.wpm >= 120 && s.stats.accuracy >= 0.95)).length },
              { nivel: '¡Bien!', cantidad: filteredStudents.filter(s => s.stats.wpm >= 80 && s.stats.accuracy >= 0.85 && !(s.stats.wpm >= 100 && s.stats.accuracy >= 0.90)).length },
              { nivel: '¡A practicar!', cantidad: filteredStudents.filter(s => s.stats.wpm < 80 || s.stats.accuracy < 0.85).length }
            ]}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e0e0e0" />
              <XAxis dataKey="nivel" />
              <YAxis />
              <Tooltip />
              <Bar dataKey="cantidad" fill="#8B5CF6" radius={[10, 10, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </motion.div>
      </div>

      {/* Student List */}
      <motion.div
        className="bg-white/90 backdrop-blur-xl border border-gray-200 rounded-2xl shadow-xl overflow-hidden"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.7 }}
      >
        {/* Filters */}
        <div className="p-6 border-b border-gray-200">
          <div className="flex flex-col sm:flex-row gap-4 items-start sm:items-center justify-between">
            <h3 className="text-xl font-bold text-gray-900">
              Mis Pequeños Lectores
            </h3>
            
            <div className="flex flex-col sm:flex-row gap-3 w-full sm:w-auto">
              <div className="relative">
                <Search className="w-5 h-5 absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                <input
                  type="text"
                  placeholder="Buscar por nombre..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-10 pr-4 py-2 border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 w-full sm:w-64 text-lg"
                />
              </div>
              
              <select
                value={sortBy}
                onChange={(e) => setSortBy(e.target.value)}
                className="px-4 py-2 border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 text-lg"
              >
                <option value="name">Ordenar por Nombre</option>
                <option value="wpm">Ordenar por WPM</option>
                <option value="accuracy">Ordenar por Precisión</option>
                <option value="lastReading">Ordenar por Fecha</option>
              </select>
            </div>
          </div>
        </div>

        {/* Table */}
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead className="bg-blue-50">
              <tr>
                <th className="px-6 py-4 text-left text-base font-bold text-blue-800">Estudiante</th>
                <th className="px-6 py-4 text-center text-base font-bold text-blue-800">WPM</th>
                <th className="px-6 py-4 text-center text-base font-bold text-blue-800">Precisión</th>
                <th className="px-6 py-4 text-center text-base font-bold text-blue-800">Nivel</th>
                <th className="px-6 py-4 text-center text-base font-bold text-blue-800">Última Lectura</th>
                <th className="px-6 py-4 text-center text-base font-bold text-blue-800">Total</th>
                <th className="px-6 py-4 text-center text-base font-bold text-blue-800">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200">
              {filteredStudents.map((student, index) => (
                <motion.tr
                  key={student.id}
                  className="hover:bg-blue-50 transition-colors"
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: index * 0.05 }}
                >
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-3">
                      <motion.div 
                        className="w-12 h-12 bg-gradient-to-br from-blue-500 to-purple-600 rounded-full flex items-center justify-center text-white font-bold text-xl shadow-md"
                        whileHover={{ scale: 1.1, rotate: 10 }}
                      >
                        {student.name.split(' ').map(n => n[0]).join('')}
                      </motion.div>
                      <div>
                        <div className="font-bold text-gray-900 text-lg">{student.name}</div>
                        <div className="text-base text-gray-600">{student.grade}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className="text-xl font-bold text-gray-900">
                      {student.stats.wpm}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className="text-xl font-bold text-gray-900">
                      {Math.round(student.stats.accuracy * 100)}%
                    </span>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className={`px-4 py-2 rounded-full text-base font-bold ${getPerformanceColor(student.stats.wpm, student.stats.accuracy)}`}>
                      {getPerformanceLabel(student.stats.wpm, student.stats.accuracy)}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-center text-base text-gray-700">
                    {new Date(student.lastReading).toLocaleDateString('es-ES')}
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className="text-base font-bold text-gray-900">
                      {student.stats.totalReadings}
                    </span>
                    <span className="text-sm text-gray-600 block">lecturas</span>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <motion.button
                      onClick={() => openStudentDetails(student)}
                      className="p-2 bg-blue-100 text-blue-700 rounded-full hover:bg-blue-200 transition-colors"
                      whileHover={{ scale: 1.1 }}
                      whileTap={{ scale: 0.9 }}
                    >
                      <Eye className="w-5 h-5" />
                    </motion.button>
                  </td>
                </motion.tr>
              ))}
            </tbody>
          </table>
        </div>
      </motion.div>

      {/* Modal de Detalles del Estudiante */}
      <AnimatePresence>
        {selectedStudent && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50"
            onClick={closeStudentDetails}
          >
            <motion.div
              initial={{ scale: 0.9, y: 50 }}
              animate={{ scale: 1, y: 0 }}
              exit={{ scale: 0.9, y: 50 }}
              transition={{ type: "spring", stiffness: 200, damping: 20 }}
              className="bg-white rounded-3xl p-8 shadow-2xl max-w-2xl w-full relative"
              onClick={(e) => e.stopPropagation()}
            >
              <motion.button
                onClick={closeStudentDetails}
                className="absolute top-4 right-4 p-2 bg-gray-100 rounded-full text-gray-600 hover:bg-gray-200 transition-colors"
                whileHover={{ scale: 1.1, rotate: 90 }}
                whileTap={{ scale: 0.9 }}
              >
                <X className="w-6 h-6" />
              </motion.button>

              <div className="text-center mb-6">
                <motion.div 
                  className="w-24 h-24 bg-gradient-to-br from-blue-500 to-purple-600 rounded-full flex items-center justify-center text-white font-bold text-4xl mx-auto mb-4 shadow-lg"
                  initial={{ scale: 0 }}
                  animate={{ scale: 1 }}
                  transition={{ type: "spring", stiffness: 260, damping: 20, delay: 0.2 }}
                >
                  {selectedStudent.name.split(' ').map(n => n[0]).join('')}
                </motion.div>
                <h2 className="text-3xl font-bold text-gray-900 mb-2">
                  {selectedStudent.name}
                </h2>
                <p className="text-lg text-gray-600">
                  {selectedStudent.grade} • {selectedStudent.age} años
                </p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                <div className="bg-blue-50 border border-blue-200 rounded-xl p-4 text-center">
                  <p className="text-blue-700 font-semibold text-lg">WPM Promedio</p>
                  <p className="text-blue-900 font-bold text-3xl">{selectedStudent.stats.wpm}</p>
                </div>
                <div className="bg-green-50 border border-green-200 rounded-xl p-4 text-center">
                  <p className="text-green-700 font-semibold text-lg">Precisión Promedio</p>
                  <p className="text-green-900 font-bold text-3xl">{Math.round(selectedStudent.stats.accuracy * 100)}%</p>
                </div>
              </div>

              <h3 className="text-xl font-bold text-gray-900 mb-4">
                Historial de Lecturas
              </h3>
              <div className="h-64">
                <ResponsiveContainer width="100%" height="100%">
                  <LineChart data={studentReadingHistory}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="date" />
                    <YAxis />
                    <Tooltip />
                    <Line type="monotone" dataKey="wpm" stroke="#8884d8" name="WPM" />
                    <Line type="monotone" dataKey="accuracy" stroke="#82ca9d" name="Precisión" />
                  </LineChart>
                </ResponsiveContainer>
              </div>
              <p className="text-center text-gray-500 text-sm mt-4">
                (Este es un historial de ejemplo. En una aplicación real, se mostrarían los datos de cada lectura del estudiante.)
              </p>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default TeacherDashboard;