import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { BookOpen, Clock, BarChart3, Play, Eye, Sparkles, Star } from 'lucide-react';
import { readingTexts } from '../data/mockTexts';

const TextSelector = ({ onSelectText, onStartReading }) => {
  const [selectedText, setSelectedText] = useState(null);
  const [showPreview, setShowPreview] = useState(false);

  const handleSelectText = (text) => {
    setSelectedText(text);
    onSelectText(text);
  };

  const getDifficultyColor = (difficulty) => {
    switch (difficulty) {
      case 'easy': return 'from-green-400 to-lime-500'; // Más brillante
      case 'medium': return 'from-yellow-400 to-orange-500'; // Más brillante
      case 'hard': return 'from-red-400 to-pink-500'; // Más brillante
      default: return 'from-blue-400 to-purple-500';
    }
  };

  const getDifficultyLabel = (difficulty) => {
    switch (difficulty) {
      case 'easy': return '¡Fácil!';
      case 'medium': return '¡Normal!';
      case 'hard': return '¡Reto!';
      default: return 'Normal';
    }
  };

  return (
    <div className="max-w-4xl mx-auto p-6">
      <motion.div
        className="text-center mb-8"
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
      >
        <div className="flex items-center justify-center gap-3 mb-4">
          <motion.div 
            className="p-3 bg-gradient-to-br from-blue-500 to-purple-600 rounded-2xl"
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ type: "spring", stiffness: 260, damping: 20 }}
          >
            <BookOpen className="w-8 h-8 text-white" />
          </motion.div>
          <h1 className="text-3xl font-bold bg-gradient-to-r from-blue-600 to-purple-700 bg-clip-text text-transparent">
            ¡Mi Aventura de Lectura!
          </h1>
        </div>
        <p className="text-gray-600 font-medium text-lg">
          Elige un cuento y ¡a leer se ha dicho!
        </p>
      </motion.div>

      <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3 mb-8">
        {readingTexts.map((text, index) => (
          <motion.div
            key={text.id}
            className={`bg-white/90 backdrop-blur-sm border-2 rounded-2xl p-6 cursor-pointer transition-all duration-300 hover:shadow-xl transform hover:-translate-y-1 ${
              selectedText?.id === text.id
                ? 'border-blue-500 bg-blue-100/50 shadow-lg'
                : 'border-gray-200 hover:border-blue-300'
            }`}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: index * 0.1 }}
            onClick={() => handleSelectText(text)}
            whileHover={{ scale: 1.03 }}
            whileTap={{ scale: 0.98 }}
          >
            <div className="flex items-start justify-between mb-4">
              <h3 className="text-xl font-bold text-gray-900">{text.title}</h3>
              <motion.div 
                className={`px-3 py-1 rounded-full bg-gradient-to-r ${getDifficultyColor(text.difficulty)} text-white text-sm font-semibold flex items-center gap-1`}
                initial={{ scale: 0 }}
                animate={{ scale: 1 }}
                transition={{ type: "spring", stiffness: 300, damping: 20, delay: index * 0.1 + 0.3 }}
              >
                <Star className="w-4 h-4 fill-current" />
                {getDifficultyLabel(text.difficulty)}
              </motion.div>
            </div>

            <div className="space-y-3 text-gray-700">
              <div className="flex items-center gap-2 text-base">
                <BarChart3 className="w-5 h-5 text-purple-500" />
                <span>Nivel: {text.level}</span>
              </div>
              
              <div className="flex items-center gap-2 text-base">
                <Clock className="w-5 h-5 text-orange-500" />
                <span>Tiempo: {text.estimatedTime}</span>
              </div>

              <div className="text-sm text-gray-600">
                {text.wordCount} palabras • Meta: {text.targetWPM} WPM
              </div>

              <p className="text-base text-gray-800 line-clamp-3">
                {text.content.substring(0, 120)}...
              </p>
            </div>
          </motion.div>
        ))}
      </div>

      {selectedText && (
        <motion.div
          className="bg-white/90 backdrop-blur-xl border border-gray-200 rounded-3xl p-6 shadow-xl"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
        >
          <div className="flex flex-col sm:flex-row gap-4 items-center justify-between">
            <div>
              <h3 className="text-2xl font-bold text-gray-900 mb-2">
                ¡Listo para leer: {selectedText.title}!
              </h3>
              <p className="text-gray-700 text-lg">
                Nivel: {selectedText.level} • Tiempo: {selectedText.estimatedTime}
              </p>
            </div>

            <div className="flex gap-3">
              <motion.button
                onClick={() => setShowPreview(!showPreview)}
                className="flex items-center gap-2 px-5 py-3 bg-yellow-100 text-yellow-700 rounded-xl font-semibold hover:bg-yellow-200 transition-colors transform hover:scale-105"
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
              >
                <Eye className="w-5 h-5" />
                Ver cuento
              </motion.button>

              <motion.button
                onClick={() => onStartReading(selectedText)}
                className="flex items-center gap-2 px-6 py-3 bg-gradient-to-r from-green-500 to-emerald-600 text-white rounded-xl font-bold shadow-lg hover:shadow-xl transition-all transform hover:scale-105"
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
              >
                <Play className="w-5 h-5" />
                ¡Empezar!
              </motion.button>
            </div>
          </div>

          {showPreview && (
            <motion.div
              className="mt-6 p-4 bg-blue-50 rounded-xl border border-blue-200"
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: 'auto' }}
              transition={{ duration: 0.3 }}
            >
              <h4 className="font-bold text-blue-800 mb-3 text-lg">El cuento completo:</h4>
              <div className="text-gray-800 leading-relaxed text-base whitespace-pre-line">
                {selectedText.content}
              </div>
            </motion.div>
          )}
        </motion.div>
      )}
    </div>
  );
};

export default TextSelector;