import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Mic, MicOff, Square, Play, Pause, Volume2, Camera, CameraOff, Smile, Frown } from 'lucide-react';

const ReadingRecorder = ({ text, onComplete, onCancel }) => {
  const [isRecording, setIsRecording] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [recordingTime, setRecordingTime] = useState(0);
  const [audioLevel, setAudioLevel] = useState(0);
  const [cameraEnabled, setCameraEnabled] = useState(false);
  const [currentWordIndex, setCurrentWordIndex] = useState(0);
  
  const mediaRecorderRef = useRef(null);
  const audioContextRef = useRef(null);
  const analyserRef = useRef(null);
  const streamRef = useRef(null);
  const intervalRef = useRef(null);

  const words = text.content.split(/\s+/);

  useEffect(() => {
    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, []);

  const startRecording = async () => {
    try {
      const constraints = {
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          sampleRate: 16000
        },
        video: cameraEnabled ? { width: 640, height: 480 } : false
      };

      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = stream;

      // Setup audio analysis
      audioContextRef.current = new AudioContext();
      analyserRef.current = audioContextRef.current.createAnalyser();
      const source = audioContextRef.current.createMediaStreamSource(stream);
      source.connect(analyserRef.current);

      // Setup media recorder
      mediaRecorderRef.current = new MediaRecorder(stream);
      const chunks = [];

      mediaRecorderRef.current.ondataavailable = (event) => {
        chunks.push(event.data);
      };

      mediaRecorderRef.current.onstop = () => {
        const blob = new Blob(chunks, { type: 'audio/webm' });
        handleRecordingComplete(blob);
      };

      mediaRecorderRef.current.start();
      setIsRecording(true);

      // Start timer and audio level monitoring
      intervalRef.current = setInterval(() => {
        setRecordingTime(prev => prev + 1);
        updateAudioLevel();
        
        // Simulate word progression (in real app, this would be based on speech recognition)
        setCurrentWordIndex(prev => {
          const newIndex = Math.min(prev + 1, words.length - 1);
          return newIndex;
        });
      }, 1000);

    } catch (error) {
      console.error('Error accessing media devices:', error);
      alert('¡Oh no! No pude usar tu micrófono. ¿Me das permiso?');
    }
  };

  const updateAudioLevel = () => {
    if (analyserRef.current) {
      const dataArray = new Uint8Array(analyserRef.current.frequencyBinCount);
      analyserRef.current.getByteFrequencyData(dataArray);
      const average = dataArray.reduce((a, b) => a + b) / dataArray.length;
      setAudioLevel(Math.min(average / 128, 1));
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
      
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    }
  };

  const handleRecordingComplete = (audioBlob) => {
    // Simulate processing time
    setTimeout(() => {
      onComplete({
        audioBlob,
        duration: recordingTime,
        wordCount: words.length,
        timestamp: new Date().toISOString()
      });
    }, 1000);
  };

  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const renderTextWithHighlight = () => {
    return text.content.split(/(\s+)/).map((part, index) => {
      const wordIndex = Math.floor(index / 2);
      const isCurrentWord = wordIndex === currentWordIndex && isRecording;
      const isReadWord = wordIndex < currentWordIndex;
      
      if (part.trim() === '') return part;
      
      return (
        <span
          key={index}
          className={`transition-all duration-300 text-2xl font-semibold ${
            isCurrentWord
              ? 'bg-yellow-300 text-blue-900 px-1 rounded-md shadow-md'
              : isReadWord
              ? 'text-green-700 opacity-70'
              : 'text-gray-800'
          }`}
        >
          {part}
        </span>
      );
    });
  };

  return (
    <div className="max-w-4xl mx-auto p-6">
      <motion.div
        className="bg-white/90 backdrop-blur-xl border border-gray-200 rounded-3xl p-8 shadow-xl"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
      >
        {/* Header */}
        <div className="text-center mb-8">
          <h2 className="text-3xl font-bold text-gray-900 mb-2">
            ¡Es hora de leer en voz alta!
          </h2>
          <p className="text-gray-600 text-lg">
            Cuento: <span className="font-semibold text-blue-600">{text.title}</span>
          </p>
        </div>

        {/* Camera Toggle */}
        <div className="flex justify-center mb-6">
          <motion.button
            onClick={() => setCameraEnabled(!cameraEnabled)}
            className={`flex items-center gap-2 px-5 py-3 rounded-xl font-semibold transition-all transform hover:scale-105 ${
              cameraEnabled
                ? 'bg-blue-100 text-blue-700 border border-blue-200'
                : 'bg-gray-100 text-gray-600 border border-gray-200'
            }`}
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            disabled={isRecording}
          >
            {cameraEnabled ? <Camera className="w-5 h-5" /> : <CameraOff className="w-5 h-5" />}
            {cameraEnabled ? 'Cámara activada' : 'Activar cámara (opcional)'}
          </motion.button>
        </div>

        {/* Text Display */}
        <div className="bg-blue-50 rounded-2xl p-6 mb-8 border-2 border-blue-200 shadow-inner">
          <div className="leading-relaxed">
            {renderTextWithHighlight()}
          </div>
        </div>

        {/* Recording Controls */}
        <div className="flex flex-col items-center gap-6">
          {/* Status Indicators */}
          <div className="flex items-center gap-6">
            <div className="flex items-center gap-2 text-lg font-medium text-gray-700">
              <motion.div 
                className="w-4 h-4 bg-red-500 rounded-full"
                animate={{ scale: [1, 1.2, 1] }}
                transition={{ repeat: Infinity, duration: 1 }}
              ></motion.div>
              <span>Tiempo: {formatTime(recordingTime)}</span>
            </div>
            
            <div className="flex items-center gap-2 text-lg font-medium text-gray-700">
              <Volume2 className="w-6 h-6 text-purple-600" />
              <div className="w-24 h-3 bg-gray-200 rounded-full overflow-hidden">
                <motion.div
                  className="h-full bg-gradient-to-r from-green-400 to-lime-500"
                  style={{ width: `${audioLevel * 100}%` }}
                  transition={{ duration: 0.1 }}
                />
              </div>
            </div>
          </div>

          {/* Main Controls */}
          <div className="flex items-center gap-4">
            <AnimatePresence mode="wait">
              {!isRecording ? (
                <motion.button
                  key="start"
                  onClick={startRecording}
                  className="flex items-center gap-3 px-8 py-4 bg-gradient-to-r from-green-500 to-emerald-600 text-white rounded-2xl font-bold shadow-lg hover:shadow-xl transition-all transform hover:scale-105"
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                  initial={{ opacity: 0, scale: 0.8 }}
                  animate={{ opacity: 1, scale: 1 }}
                  exit={{ opacity: 0, scale: 0.8 }}
                >
                  <Mic className="w-6 h-6" />
                  ¡Grabar mi lectura!
                </motion.button>
              ) : (
                <motion.button
                  key="stop"
                  onClick={stopRecording}
                  className="flex items-center gap-3 px-8 py-4 bg-gradient-to-r from-red-500 to-pink-600 text-white rounded-2xl font-bold shadow-lg hover:shadow-xl transition-all transform hover:scale-105"
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                  initial={{ opacity: 0, scale: 0.8 }}
                  animate={{ opacity: 1, scale: 1 }}
                  exit={{ opacity: 0, scale: 0.8 }}
                >
                  <Square className="w-6 h-6" />
                  ¡Terminar!
                </motion.button>
              )}
            </AnimatePresence>

            <motion.button
              onClick={onCancel}
              className="px-6 py-3 bg-gray-100 text-gray-700 rounded-xl font-semibold hover:bg-gray-200 transition-colors transform hover:scale-105"
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
            >
              Cancelar
            </motion.button>
          </div>

          {/* Progress */}
          {isRecording && (
            <motion.div
              className="w-full max-w-md"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 0.5 }}
            >
              <div className="flex justify-between text-base text-gray-700 mb-2 font-medium">
                <span>¡Vamos, sigue leyendo!</span>
                <span>{Math.round((currentWordIndex / words.length) * 100)}%</span>
              </div>
              <div className="w-full h-4 bg-gray-200 rounded-full overflow-hidden shadow-inner">
                <motion.div
                  className="h-full bg-gradient-to-r from-blue-400 to-purple-500"
                  style={{ width: `${(currentWordIndex / words.length) * 100}%` }}
                  transition={{ duration: 0.5 }}
                />
              </div>
            </motion.div>
          )}
        </div>
      </motion.div>
    </div>
  );
};

export default ReadingRecorder;