import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Volume2, 
  Play, 
  Pause, 
  SkipForward, 
  CheckCircle, 
  RotateCcw,
  BookOpen,
  Target,
  Sparkles,
  Lightbulb,
  MessageSquare
} from 'lucide-react';
import { generatePracticeWords } from '../utils/readingUtils';

const PracticeMode = ({ difficultWords, onComplete, onBack }) => {
  const [currentWordIndex, setCurrentWordIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [completedWords, setCompletedWords] = useState(new Set());
  const [practiceMode, setPracticeMode] = useState('syllables'); // 'syllables' | 'whole' | 'context'

  const practiceWords = generatePracticeWords(difficultWords);
  const currentWord = practiceWords[currentWordIndex];

  const handleWordComplete = () => {
    setCompletedWords(prev => new Set([...prev, currentWordIndex]));
    if (currentWordIndex < practiceWords.length - 1) {
      setCurrentWordIndex(prev => prev + 1);
    }
  };

  const handleNext = () => {
    if (currentWordIndex < practiceWords.length - 1) {
      setCurrentWordIndex(prev => prev + 1);
    }
  };

  const handlePrevious = () => {
    if (currentWordIndex > 0) {
      setCurrentWordIndex(prev => prev - 1);
    }
  };

  const playWordAudio = () => {
    // In a real app, this would use text-to-speech
    setIsPlaying(true);
    setTimeout(() => setIsPlaying(false), 1000);
  };

  const getContextSentence = (word) => {
    const sentences = [
      `¡Vamos a usar "${word}" en una frase!`,
      `Mira cómo suena "${word}" aquí:`,
      `Esta es una frase con "${word}":`,
      `¿Puedes leer esta frase con "${word}"?`
    ];
    const exampleSentences = [
      `La ${word} es muy importante para entender el tema.`,
      `Necesitamos estudiar más sobre ${word} en clase.`,
      `El profesor explicó el concepto de ${word} muy bien.`,
      `¿Puedes repetir la palabra ${word} por favor?`
    ];
    return {
      intro: sentences[Math.floor(Math.random() * sentences.length)],
      sentence: exampleSentences[Math.floor(Math.random() * exampleSentences.length)]
    };
  };

  const renderSyllablePractice = () => (
    <div className="text-center">
      <h3 className="text-2xl font-bold text-gray-900 mb-6">
        ¡Divide y vencerás!
      </h3>
      <div className="flex justify-center items-center gap-3 mb-8 flex-wrap">
        {currentWord.syllables.map((syllable, index) => (
          <motion.div
            key={index}
            className="px-5 py-3 bg-gradient-to-r from-blue-200 to-purple-200 border-2 border-blue-400 rounded-xl text-3xl font-bold text-blue-900 shadow-md"
            initial={{ opacity: 0, scale: 0.8 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ type: "spring", stiffness: 260, damping: 20, delay: index * 0.1 }}
            whileHover={{ scale: 1.1, rotate: 5 }}
          >
            {syllable}
          </motion.div>
        ))}
      </div>
      <motion.div 
        className="text-5xl font-bold text-gray-900 mb-4 p-4 bg-yellow-100 rounded-xl border-2 border-yellow-300 shadow-lg"
        initial={{ scale: 0.9 }}
        animate={{ scale: 1 }}
        transition={{ type: "spring", stiffness: 200, damping: 15 }}
      >
        {currentWord.word}
      </motion.div>
    </div>
  );

  const renderWholePractice = () => (
    <div className="text-center">
      <h3 className="text-2xl font-bold text-gray-900 mb-6">
        ¡La palabra completa!
      </h3>
      <motion.div
        className="text-6xl font-bold text-gray-900 mb-8 p-8 bg-gradient-to-r from-green-100 to-lime-100 border-2 border-green-400 rounded-2xl shadow-xl"
        initial={{ scale: 0.8, rotate: -5 }}
        animate={{ scale: 1, rotate: 0 }}
        transition={{ type: "spring", stiffness: 200, damping: 15 }}
        whileHover={{ scale: 1.05, rotate: 3 }}
      >
        {currentWord.word}
      </motion.div>
    </div>
  );

  const renderContextPractice = () => {
    const { intro, sentence } = getContextSentence(currentWord.word);
    return (
      <div className="text-center">
        <h3 className="text-2xl font-bold text-gray-900 mb-6">
          ¡En una frase!
        </h3>
        <motion.p 
          className="text-xl text-gray-700 mb-4"
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
        >
          {intro}
        </motion.p>
        <motion.div
          className="text-2xl leading-relaxed text-gray-800 mb-8 p-6 bg-purple-100 rounded-2xl border-2 border-purple-300 shadow-md"
          initial={{ scale: 0.9 }}
          animate={{ scale: 1 }}
          transition={{ type: "spring", stiffness: 200, damping: 15 }}
        >
          {sentence.split(currentWord.word).map((part, index, array) => (
            <span key={index}>
              {part}
              {index < array.length - 1 && (
                <span className="bg-yellow-300 text-yellow-900 px-2 py-1 rounded font-bold shadow-sm">
                  {currentWord.word}
                </span>
              )}
            </span>
          ))}
        </motion.div>
      </div>
    );
  };

  const renderPracticeContent = () => {
    switch (practiceMode) {
      case 'syllables':
        return renderSyllablePractice();
      case 'whole':
        return renderWholePractice();
      case 'context':
        return renderContextPractice();
      default:
        return renderWholePractice();
    }
  };

  return (
    <div className="max-w-4xl mx-auto p-6">
      <motion.div
        className="bg-white/90 backdrop-blur-xl border border-gray-200 rounded-3xl p-8 shadow-xl"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
      >
        {/* Header */}
        <div className="text-center mb-8">
          <motion.div
            className="w-20 h-20 bg-gradient-to-br from-green-500 to-emerald-600 rounded-full flex items-center justify-center mx-auto mb-4 shadow-lg"
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ delay: 0.2, type: "spring", stiffness: 260, damping: 20 }}
          >
            <Target className="w-10 h-10 text-white" />
          </motion.div>
          <h2 className="text-4xl font-bold bg-gradient-to-r from-green-600 to-emerald-700 bg-clip-text text-transparent mb-2">
            ¡Hora de Practicar!
          </h2>
          <p className="text-gray-700 text-xl">
            Palabra {currentWordIndex + 1} de {practiceWords.length}
          </p>
        </div>

        {/* Progress Bar */}
        <div className="mb-8">
          <div className="flex justify-between text-lg text-gray-700 mb-2 font-medium">
            <span>¡Vamos, tú puedes!</span>
            <span>{Math.round(((currentWordIndex + 1) / practiceWords.length) * 100)}%</span>
          </div>
          <div className="w-full h-4 bg-gray-200 rounded-full overflow-hidden shadow-inner">
            <motion.div
              className="h-full bg-gradient-to-r from-yellow-400 to-orange-500"
              style={{ width: `${((currentWordIndex + 1) / practiceWords.length) * 100}%` }}
              transition={{ duration: 0.5 }}
            />
          </div>
        </div>

        {/* Practice Mode Selector */}
        <div className="flex justify-center mb-8">
          <div className="flex bg-gray-100 rounded-2xl p-1 gap-1 shadow-inner">
            {[
              { key: 'syllables', label: 'Por Sílabas', icon: Lightbulb },
              { key: 'whole', label: 'Completa', icon: Sparkles },
              { key: 'context', label: 'En Frase', icon: MessageSquare }
            ].map(({ key, label, icon: Icon }) => (
              <motion.button
                key={key}
                onClick={() => setPracticeMode(key)}
                className={`flex items-center gap-2 px-5 py-3 rounded-xl font-bold text-lg transition-all transform hover:scale-105 ${
                  practiceMode === key
                    ? 'bg-white text-gray-900 shadow-md'
                    : 'text-gray-600 hover:text-gray-900 hover:bg-white/50'
                }`}
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
              >
                <Icon className="w-5 h-5" />
                {label}
              </motion.button>
            ))}
          </div>
        </div>

        {/* Practice Content */}
        <AnimatePresence mode="wait">
          <motion.div
            key={practiceMode + currentWordIndex}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            transition={{ duration: 0.3 }}
            className="mb-8"
          >
            {renderPracticeContent()}
          </motion.div>
        </AnimatePresence>

        {/* Audio Controls */}
        <div className="flex justify-center mb-8">
          <motion.button
            onClick={playWordAudio}
            disabled={isPlaying}
            className={`flex items-center gap-2 px-7 py-4 rounded-2xl font-bold transition-all transform hover:scale-105 ${
              isPlaying
                ? 'bg-gray-300 text-gray-500 cursor-not-allowed'
                : 'bg-gradient-to-r from-blue-500 to-purple-600 text-white shadow-lg hover:shadow-xl'
            }`}
            whileHover={!isPlaying ? { scale: 1.05 } : {}}
            whileTap={!isPlaying ? { scale: 0.95 } : {}}
          >
            {isPlaying ? (
              <>
                <Pause className="w-6 h-6" />
                ¡Escuchando!
              </>
            ) : (
              <>
                <Play className="w-6 h-6" />
                ¡Escúchame!
              </>
            )}
          </motion.button>
        </div>

        {/* Navigation Controls */}
        <div className="flex justify-center items-center gap-4 mb-8">
          <motion.button
            onClick={handlePrevious}
            disabled={currentWordIndex === 0}
            className={`p-4 rounded-xl transition-all transform ${
              currentWordIndex === 0
                ? 'bg-gray-100 text-gray-400 cursor-not-allowed'
                : 'bg-blue-100 text-blue-700 hover:bg-blue-200 hover:scale-110'
            }`}
            whileHover={currentWordIndex > 0 ? { scale: 1.1 } : {}}
            whileTap={currentWordIndex > 0 ? { scale: 0.9 } : {}}
          >
            <RotateCcw className="w-6 h-6" />
          </motion.button>

          <motion.button
            onClick={handleWordComplete}
            className="flex items-center gap-2 px-7 py-4 bg-gradient-to-r from-green-500 to-emerald-600 text-white rounded-2xl font-bold shadow-lg hover:shadow-xl transition-all transform hover:scale-105"
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
          >
            <CheckCircle className="w-6 h-6" />
            ¡Ya la sé!
          </motion.button>

          <motion.button
            onClick={handleNext}
            disabled={currentWordIndex === practiceWords.length - 1}
            className={`p-4 rounded-xl transition-all transform ${
              currentWordIndex === practiceWords.length - 1
                ? 'bg-gray-100 text-gray-400 cursor-not-allowed'
                : 'bg-blue-100 text-blue-700 hover:bg-blue-200 hover:scale-110'
            }`}
            whileHover={currentWordIndex < practiceWords.length - 1 ? { scale: 1.1 } : {}}
            whileTap={currentWordIndex < practiceWords.length - 1 ? { scale: 0.9 } : {}}
          >
            <SkipForward className="w-6 h-6" />
          </motion.button>
        </div>

        {/* Completion Status */}
        <div className="grid grid-cols-5 sm:grid-cols-10 gap-3 mb-8">
          {practiceWords.map((_, index) => (
            <motion.div
              key={index}
              className={`aspect-square rounded-lg border-2 flex items-center justify-center text-xl font-bold transition-all shadow-sm ${
                index === currentWordIndex
                  ? 'border-blue-500 bg-blue-200 text-blue-800'
                  : completedWords.has(index)
                  ? 'border-green-500 bg-green-200 text-green-800'
                  : 'border-gray-300 bg-gray-100 text-gray-500'
              }`}
              initial={{ scale: 0.8 }}
              animate={{ scale: 1 }}
              transition={{ type: "spring", stiffness: 300, damping: 20, delay: index * 0.05 }}
            >
              {completedWords.has(index) ? (
                <CheckCircle className="w-6 h-6 text-green-600" />
              ) : (
                index + 1
              )}
            </motion.div>
          ))}
        </div>

        {/* Action Buttons */}
        <div className="flex flex-col sm:flex-row gap-4 justify-center">
          {completedWords.size === practiceWords.length ? (
            <motion.button
              onClick={onComplete}
              className="flex items-center gap-2 px-8 py-4 bg-gradient-to-r from-green-500 to-emerald-600 text-white rounded-xl font-bold shadow-lg hover:shadow-xl transition-all transform hover:scale-105"
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
            >
              <Sparkles className="w-6 h-6" />
              ¡Práctica Terminada!
            </motion.button>
          ) : (
            <motion.button
              onClick={onComplete}
              className="px-7 py-4 bg-gradient-to-r from-blue-500 to-purple-600 text-white rounded-xl font-bold shadow-lg hover:shadow-xl transition-all transform hover:scale-105"
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
            >
              Terminar práctica
            </motion.button>
          )}

          <motion.button
            onClick={onBack}
            className="px-7 py-4 bg-gray-100 text-gray-700 rounded-xl font-bold hover:bg-gray-200 transition-colors transform hover:scale-105"
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
          >
            Volver a resultados
          </motion.button>
        </div>
      </motion.div>
    </div>
  );
};

export default PracticeMode;